+                .setWaitForActiveShards(ActiveShardCount.NONE)
+                .get()
+        );
+
+        // * 2 since worst case is no hard links, see DiskThresholdDecider.getExpectedShardSize.
+        long requiredSpaceForShrink = used * 2 + LOW_WATERMARK_BYTES;
