+        assertThat(client().admin().cluster().prepareHealth(shrinkName).get().getUnassignedShards(), equalTo(1));
+        setTotalSpace(dataNode1Name, tooLittleSpaceForShrink + 1);
+        assertAcked(client().admin().cluster().prepareReroute());
+        ensureGreen();
+    }
