+public class HealthMetadataSerializationTests extends SimpleDiffableSerializationTestCase<Metadata.Custom> {
+
+    @Override
+    protected Metadata.Custom makeTestChanges(Metadata.Custom testInstance) {
+        if (randomBoolean()) {
+            return testInstance;
+        }
